mapper.update:
UPDATE asts_task
SET status = 'RUNNING',
    version = version + 1,
    started_at = COALESCE(started_at, #{startedAt}),
    updated_at = #{startedAt}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND execution_token = #{executionToken}
  AND status = 'RUNNING'
  AND is_deleted = 0

UPDATE asts_task
SET lease_expire_at = #{now} + (#{leaseSeconds} || ' seconds')::INTERVAL,
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND execution_token = #{executionToken}
  AND status = 'RUNNING'
  AND is_deleted = 0

UPDATE asts_task
SET current_step_key = #{currentStepKey},
    current_step_progress = #{stepProgress},
    steps_detail = #{stepsDetail}::jsonb,
    progress = #{globalProgress},
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND execution_token = #{executionToken}
  AND status IN ('RUNNING', 'CANCELLING')
  AND is_deleted = 0

UPDATE asts_task
SET status = 'CANCELLING',
    version = version + 1,
    requested_cancel_at = #{requestedCancelAt},
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status IN ('PENDING', 'RUNNING')
  AND is_deleted = 0

UPDATE asts_task
SET status = 'CANCELLED',
    version = version + 1,
    finished_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND execution_token = #{executionToken}
  AND status = 'CANCELLING'
  AND is_deleted = 0
